-- Đổi tên users.fullname thành display_name
-- 1) Expand (deploy 1): thêm cột, code ghi cả hai
ALTER TABLE users ADD COLUMN display_name text;

-- 2) Migrate: backfill theo lô, rồi deploy 2 đọc từ cột mới
UPDATE users SET display_name = fullname
WHERE id BETWEEN 1 AND 10000 AND display_name IS NULL;

-- 3) Contract (deploy 3): code ngừng ghi cột cũ, sau đó mới xoá
ALTER TABLE users DROP COLUMN fullname;
